## Why This Is Asked
Maintaining the median under dynamic inserts and deletes is a common, practical data-structure task that tests understanding of balanced structures and handling edge cases with duplicates.

## Key Concepts
- Median of a dynamic multiset
- Heaps: max-heap for lower half, min-heap for upper half
- Lazy deletion via hashmap to avoid O(n) removal
- Balancing logic and handling duplicates with reference counting

## Code Example
```javascript
class MedianSet {
  constructor() {
    this.low = new MaxHeap();
    this.high = new MinHeap();
    this.delLow = new Map();
    this.delHigh = new Map();
  }

  _prune() {
    while (this.low.size() > 0 && this.delLow.has(this.low.peek())) {
      const count = this.delLow.get(this.low.peek()) - 1;
      if (count <= 0) this.delLow.delete(this.low.peek());
      else this.delLow.set(this.low.peek(), count);
      this.low.pop();
    }
    while (this.high.size() > 0 && this.delHigh.has(this.high.peek())) {
      const count = this.delHigh.get(this.high.peek()) - 1;
      if (count <= 0) this.delHigh.delete(this.high.peek());
      else this.delHigh.set(this.high.peek(), count);
      this.high.pop();
    }
  }

  _rebalance() {
    if (this.low.size() > this.high.size() + 1) {
      this.high.push(this.low.pop());
    } else if (this.high.size() > this.low.size() + 1) {
      this.low.push(this.high.pop());
    }
  }

  insertScore(x) {
    if (this.low.size() === 0 || x <= this.low.peek()) {
      this.low.push(x);
    } else {
      this.high.push(x);
    }
    this._rebalance();
  }

  removeScore(x) {
    if (this.low.size() > 0 && x <= this.low.peek()) {
      const count = this.delLow.get(x) || 0;
      this.delLow.set(x, count + 1);
    } else {
      const count = this.delHigh.get(x) || 0;
      this.delHigh.set(x, count + 1);
    }
    this._prune();
    this._rebalance();
  }

  getMedian() {
    this._prune();
    if (this.low.size() > this.high.size()) return this.low.peek();
    if (this.high.size() > this.low.size()) return this.high.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}
```

## Why This Is Asked

This question tests mastery of rope-like data structures for dynamic sequences with cut-paste operations while maintaining fast range queries.

## Key Concepts

- **Implicit treap / rope**: Uses position as the key rather than explicit values
- **Split and merge operations**: Fundamental primitives for manipulating segments
- **Augmented data**: size and range sum maintained at each node
- **Edge cases**: Properly handling when dest overlaps with [l, r]

## Code Example

```javascript
class Node {
  constructor(v) {
    this.v = v;
    this.pr = Math.random();
    this.l = this.r = null;
    this.sz = 1;
    this.sum = v;
  }
}

function upd(t) {
  if (!t) return;
  t.sz = 1 + sz(t.l) + sz(t.r);
  t.sum = t.v + sum(t.l) + sum(t.r);
}

function split(t, k, l, r) {
  if (!t) return [null, null];
  if (sz(t.l) >= k) {
    let [a, b] = split(t.l, k, l, r);
    t.l = b; upd(t);
    return [a, t];
  } else {
    let [a, b] = split(t.r, k - sz(t.l) - 1, l, r);
    t.r = a; upd(t);
    return [t, b];
  }
}

function merge(a, b) {
  if (!a || !b) return a || b;
  if (a.pr < b.pr) {
    a.r = merge(a.r, b); upd(a); return a;
  } else {
    b.l = merge(a, b.l); upd(b); return b;
  }
}

function rangeSum(t, l, r) {
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, r - l + 1);
  let res = sum(b);
  t = merge(a, merge(b, c));
  return res;
}

function moveSegment(t, l, r, dest) {
  let len = r - l + 1;
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, len);
  t = merge(a, c);

  let pos = dest <= l ? dest : dest - len;
  let [x, y] = split(t, pos);\n  return merge(merge(x, b), y);
}
```

